'use strict';
window.installRoundCircleDesigner=function({sim,control,group,notice,tab}){
const $=s=>document.querySelector(s),{WaveRunner,validateWave,validateLibrary,seed}=RoundCircleWaves,{types,profileStats,redistribute}=RoundCircleSimulation,clone=x=>JSON.parse(JSON.stringify(x));
const runner=new WaveRunner(sim);let library=clone(seed),draft=clone(library.waves[0]);
try{const data=localStorage.getItem('round-circle-waves-v1');if(data)library=validateLibrary(JSON.parse(data),types);}catch{notice('Bibliothèque locale invalide : exemples chargés.');}
function el(tag,text,host){const n=document.createElement(tag);if(text)n.textContent=text;if(host)host.append(n);return n;}
function button(text,host,fn){const b=el('button',text,host);b.type='button';b.onclick=()=>{try{fn();}catch(e){notice(e.message);}};return b;}
function persist(){try{localStorage.setItem('round-circle-waves-v1',JSON.stringify(library));}catch{notice('Sauvegarde locale indisponible : exporte la bibliothèque JSON.');}}
function select(host,options,value,change){const n=el('select',null,host);for(const [val,text] of options){const o=el('option',text,n);o.value=val;}n.value=value;n.onchange=()=>change(n.value);return n;}
const play=$('#play');el('h2','Profil des prochains soldats',play);el('p','Le budget est partagé : augmente une stat, les autres allocations diminuent. Les soldats déjà nés conservent leurs stats.',play);
control(play,'Production des maisons',sim.cfg,'production',0,0,0,()=>{},'checkbox');control(play,'Utiliser le profil pondéré',sim.cfg,'useBudget',0,0,0,()=>{},'checkbox');const profileHost=el('div',null,play),result=el('div',null,play);result.className='profile-result';
function updateProfile(){profileHost.querySelectorAll('label').forEach((row,i)=>{const k=Object.keys(sim.profile.shares)[i];row.querySelectorAll('input').forEach(input=>input.value=+sim.profile.shares[k].toFixed(2));});const p=profileStats(sim.profile);result.textContent=p.maxHp+' HP · '+p.damage+' dégâts · '+p.speed+' vitesse · '+p.range+' portée · '+(1/p.cooldown).toFixed(2)+' tirs/s';}
function profileUi(){profileHost.innerHTML='';for(const [k,label] of Object.entries({hp:'Résistance',damage:'Puissance',speed:'Mobilité',range:'Portée',rate:'Cadence'}))control(profileHost,label+' (%)',sim.profile.shares,k,0,100,.1,value=>{redistribute(sim.profile.shares,k,value);updateProfile();});updateProfile();}
profileUi();button('Faire naître un soldat de ce profil',play,()=>{const b=sim.buildings.find(b=>b.hp>0&&!b.dead);if(!b)throw Error('Aucun bâtiment vivant');sim.spawnActor(b,profileStats(sim.profile));});
let g=group(play,'Budget et pondérations du gym');g.open=false;control(g,'Budget total',sim.profile,'budget',10,300,1,updateProfile);for(const [k,label] of Object.entries({hp:'Coût résistance',damage:'Coût puissance',speed:'Coût mobilité',range:'Coût portée',rate:'Coût cadence'}))control(g,label,sim.profile.weights,k,.25,5,.05,updateProfile);
g=group(play,'Maisons et collisions');control(g,'Bâtiments au prochain reset',sim.cfg,'buildingCount',0,12);control(g,'Régénération (HP/s)',sim.cfg,'buildingRegen',0,20,.1,n=>sim.buildings.filter(b=>!b.dead).forEach(b=>b.regen=n));control(g,'Production (soldats/min)',sim.cfg,'buildingSpawnRate',0,60,.5,n=>sim.buildings.filter(b=>!b.dead).forEach(b=>b.spawnRate=n));control(g,'Limite soldats',sim.cfg,'actorLimit',1,300);control(g,'Limite monstres',sim.cfg,'monsterLimit',1,300);control(g,'Impact / unité de vitesse',sim.cfg,'ramDamage',0,30,.1);control(g,'Usure / unité de vitesse',sim.cfg,'ramSelfDamage',0,1,.005);el('p','Les maisons détruites restent détruites jusqu’au reset. La locomotive et chaque wagon prennent leur propre usure à l’impact.',g);
const waveHost=$('#waves');el('h2','Designer de vagues',waveHost);const saved=el('div',null,waveHost),edit=el('div',null,waveHost),playlistHost=el('div',null,waveHost);const status=el('p',null,waveHost);status.className='wave-status';
function editWave(w){draft=clone(w);renderEditor();}
function newId(){return 'wave-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);}
function renderSaved(){saved.innerHTML='';const row=el('div',null,saved);row.className='row';const chooser=select(row,library.waves.map(w=>[w.id,w.name]),draft.id,id=>editWave(library.waves.find(w=>w.id===id)));chooser.setAttribute('aria-label','Vague sauvegardée');button('Nouvelle',row,()=>editWave({id:newId(),name:'Nouvelle vague',groups:[{type:'maw',count:4,delay:0,interval:1,stats:{}}]}));}
function renderEditor(){edit.innerHTML='';const label=el('label','Nom',edit),name=el('input',null,label);name.type='text';name.maxLength=80;name.value=draft.name;name.oninput=()=>draft.name=name.value;
 draft.groups.forEach((item,i)=>{const card=el('details',null,edit);card.open=true;el('summary','Groupe '+(i+1)+' · '+types[item.type].name,card);const row=el('div',null,card);row.className='row';select(row,Object.entries(types).map(([id,t])=>[id,(t.elite?'★ ':'')+t.name]),item.type,value=>{item.type=value;item.stats={};renderEditor();});button('Retirer',row,()=>{draft.groups.splice(i,1);renderEditor();});control(card,'Quantité',item,'count',1,100);control(card,'Départ après (s)',item,'delay',0,600,.1);control(card,'Intervalle (s)',item,'interval',0,60,.1);const stats=group(card,'Stats de ce groupe');stats.open=false;for(const [k,n,min,max,step] of [['hp','HP',1,10000,1],['damage','Dégâts',0,1000,1],['speed','Vitesse',0,15,.1],['range','Portée',.1,20,.1],['cooldown','Intervalle attaque',.05,30,.05]]){if(item.stats[k]===undefined)item.stats[k]=types[item.type][k];control(stats,n,item.stats,k,min,max,step);}});
 button('+ Groupe',edit,()=>{if(draft.groups.length>=32)throw Error('Maximum 32 groupes');draft.groups.push({type:'maw',count:3,delay:0,interval:1,stats:{}});renderEditor();});const actions=el('div',null,edit);actions.className='row';button('Spawn wave',actions,()=>{runner.runWave(validateWave(draft,types));notice('Vague lancée avec les paramètres du brouillon.');});button('Sauvegarder',actions,()=>{const valid=validateWave(draft,types),index=library.waves.findIndex(w=>w.id===valid.id);if(index<0){if(library.waves.length>=100)throw Error('Maximum 100 vagues');library.waves.push(valid);}else library.waves[index]=valid;persist();renderSaved();renderPlaylist();notice('Vague sauvegardée : '+valid.name);});button('Dupliquer',actions,()=>editWave({...clone(draft),id:newId(),name:(draft.name+' copie').slice(0,80)}));renderSaved();}
 function renderPlaylist(){playlistHost.innerHTML='';el('h2','Playlist',playlistHost);el('p','Temps = délai après la dernière apparition. Élimination = attend aussi la mort des monstres de cette vague. Les changements s’appliquent au prochain lancement.',playlistHost);const add=el('div',null,playlistHost);add.className='row';let id=library.waves[0]?.id;select(add,library.waves.map(w=>[w.id,w.name]),id,val=>id=val);button('+ Ajouter',add,()=>{if(!id||library.playlist.length>=100)throw Error('Playlist pleine ou sans vague');library.playlist.push({waveId:id,mode:'clear',gap:3});persist();renderPlaylist();});
 library.playlist.forEach((item,i)=>{const card=el('div',null,playlistHost);card.className='playlist-card';el('b',(i+1)+'. '+library.waves.find(w=>w.id===item.waveId).name,card);const row=el('div',null,card);row.className='row';button('↑',row,()=>{if(i){[library.playlist[i-1],library.playlist[i]]=[item,library.playlist[i-1]];persist();renderPlaylist();}});button('↓',row,()=>{if(i<library.playlist.length-1){[library.playlist[i+1],library.playlist[i]]=[item,library.playlist[i+1]];persist();renderPlaylist();}});button('Retirer',row,()=>{library.playlist.splice(i,1);persist();renderPlaylist();});select(card,[['clear','Attendre élimination'],['time','Attendre le délai']],item.mode,val=>{item.mode=val;persist();});control(card,'Délai après vague (s)',item,'gap',0,600,.5,persist);});
 const actions=el('div',null,playlistHost);actions.className='row';button('Lancer playlist',actions,()=>runner.start(library));button('Arrêter',actions,()=>{runner.stop();notice('Planning arrêté. Les monstres présents restent en scène.');});button('Recommencer',actions,()=>{sim.reset();runner.start(library);notice('Scène remise à zéro; playlist relancée.');});
 const io=el('div',null,playlistHost);io.className='row';button('Exporter vagues',io,()=>{const data=validateLibrary(library,types),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='round-circle-vagues.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});const input=el('input',null,io);input.type='file';input.accept='.json,application/json';input.hidden=true;input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>1000000)throw Error('Fichier trop gros (1 Mo maximum)');const validated=validateLibrary(JSON.parse(await file.text()),types);library=validated;draft=clone(library.waves[0]||{id:newId(),name:'Nouvelle vague',groups:[]});persist();renderEditor();renderPlaylist();notice('Bibliothèque importée. Séquence en cours conservée.');}catch(e){notice('Import refusé : '+e.message);}finally{input.value='';}};button('Importer JSON',io,()=>input.click());}
 draft=clone(library.waves[0]||draft);renderEditor();renderPlaylist();
 return {runner,update(){runner.tick();status.textContent=runner.state+' · '+runner.jobs.length+' apparitions en attente';},refreshProfile:profileUi,getLibrary:()=>clone(library)};
};
